def s(region, diff, cat, country, answer, definition, wiki, claim):
    return dict(region=region, difficulty=diff, kind="single", category=cat, country=country, answer=answer, definition=definition, wiki=wiki, claim=claim)

def add(rows, region, cat, items):
    for item in items:
        rows.append(s(region, item[0], cat, item[1], item[2], item[3], item[4], item[5]))

